"use strict";

const crypto = require("node:crypto");
const {
  validateLiveMonitoringFeed,
  validateMonitoringBundle
} = require("../../dashboard/app.js");
const {
  computeMonitoringManifestHash,
  stableStringify
} = require("./rehearsal-acceptance");

const COLLECTOR_ADAPTER = Object.freeze({
  id: "eu5-stream-rehearsal-collector",
  version: "1"
});
const LOCAL_HEALTH_EVIDENCE =
  "Local adapter status generated by the loopback-only monitoring server.";
const LEDGER_UNVERIFIED_EVIDENCE =
  "Local append-only protocol record; external execution and game state are not independently verified.";
const LEDGER_VERIFIED_EVIDENCE =
  "Independent signed verification recorded in append-only control ledger.";
const TELEMETRY_VERIFIED_EVIDENCE =
  "Typed telemetry matched externally authenticated campaign, capture-session and reviewed-manifest evidence.";
const REQUIRED_FINGERPRINT_FIELDS = Object.freeze([
  "campaignId",
  "countryId",
  "gameBuild",
  "modVersion",
  "modManifestSha256",
  "seedSaveSha256"
]);
const IMPORTED_RECORD_TYPES = new Set([
  "llm_action_proposed",
  "llm_action_outcome",
  "nation_snapshot"
]);
const SHA256_PATTERN = /^[a-f0-9]{64}$/;
const COLLECTOR_LIMITS = Object.freeze({
  maximumFeedRecords: 2_000,
  maximumCollectedRecords: 2_000,
  maximumFeeds: 2_000,
  maximumBoundedAdvances: 1_994,
  completionRecords: 5
});

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function requireString(value, label) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function parseUtc(value, label) {
  requireString(value, label);
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed) || !value.endsWith("Z")) {
    throw new TypeError(`${label} must be a UTC ISO-8601 timestamp`);
  }
  return parsed;
}

function requireSha256(value, label) {
  if (!SHA256_PATTERN.test(value || "")) {
    throw new TypeError(`${label} must be a lowercase SHA-256`);
  }
  return value;
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function deepFreeze(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function recordDigest(record) {
  const candidate = clone(record);
  delete candidate.sequence;
  return crypto.createHash("sha256").update(stableStringify(candidate)).digest("hex");
}

function liveManifestHash(feed) {
  return crypto.createHash("sha256")
    .update(JSON.stringify(feed.records))
    .digest("hex");
}

function gameDateOrdinal(value, label) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value || "");
  if (!match) throw new TypeError(`${label} must use YYYY-MM-DD`);
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const timestamp = Date.UTC(year, month - 1, day);
  const date = new Date(timestamp);
  if (
    year < 100 ||
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new TypeError(`${label} must be a valid calendar date`);
  }
  return Math.floor(timestamp / 86_400_000);
}

function collectorProvenance(evidence, rawArtifactSha256) {
  return {
    adapter: COLLECTOR_ADAPTER,
    verification: {
      status: "verified",
      evidence
    },
    freshness: "fresh",
    ...(rawArtifactSha256 ? { rawArtifactSha256 } : {})
  };
}

class StreamRehearsalCollector {
  constructor({
    rehearsalId,
    fingerprint,
    fingerprintEvidenceSha256,
    startedAtUtc
  }) {
    this.rehearsalId = requireString(rehearsalId, "rehearsalId");
    if (!isPlainObject(fingerprint)) throw new TypeError("fingerprint must be an object");
    this.fingerprint = {};
    for (const field of REQUIRED_FINGERPRINT_FIELDS) {
      const value = requireString(fingerprint[field], `fingerprint.${field}`);
      this.fingerprint[field] = field.endsWith("Sha256")
        ? requireSha256(value, `fingerprint.${field}`)
        : value;
    }
    this.fingerprintEvidenceSha256 = requireSha256(
      fingerprintEvidenceSha256,
      "fingerprintEvidenceSha256"
    );
    this.startedAtUtc = new Date(parseUtc(startedAtUtc, "startedAtUtc")).toISOString();
    this.startedAtMs = Date.parse(this.startedAtUtc);
    this.lastFeedAtMs = null;
    this.finalFeed = null;
    this.feedIds = new Set();
    this.records = new Map();
    this.sourceHealth = new Map();
    this.boundedEvidencePairs = new Set();
    this.boundedEvidenceIntervals = [];
    this.feedCount = 0;
    this.completed = false;
    this.addCollectorRecord({
      recordId: `rehearsal-started-${this.rehearsalId}`,
      recordType: "game_event",
      occurredAtUtc: this.startedAtUtc,
      recordedAtUtc: this.startedAtUtc,
      payload: {
        eventType: "rehearsal_started",
        rehearsalId: this.rehearsalId
      },
      provenance: collectorProvenance(
        "Explicit local rehearsal capture boundary."
      )
    });
  }

  sessionFields() {
    return {
      captureSessionId: this.rehearsalId,
      subject: {
        campaignId: this.fingerprint.campaignId,
        countryId: this.fingerprint.countryId
      }
    };
  }

  addCollectorRecord(record, options) {
    return this.addRecord({
      ...record,
      ...this.sessionFields()
    }, options);
  }

  addRecord(record, { completionRecord = false } = {}) {
    if (this.completed) throw new Error("rehearsal collection is already complete");
    const candidate = clone(record);
    // Live-feed sequence numbers are snapshot-local and may change as newer
    // records are inserted. The immutable bundle assigns its own sequence.
    delete candidate.sequence;
    const existing = this.records.get(candidate.recordId);
    if (existing) {
      if (stableStringify(existing) !== stableStringify(candidate)) {
        throw new Error(`recordId ${candidate.recordId} changed after capture`);
      }
      return existing;
    }
    const recordLimit = completionRecord
      ? COLLECTOR_LIMITS.maximumCollectedRecords
      : COLLECTOR_LIMITS.maximumCollectedRecords -
        COLLECTOR_LIMITS.completionRecords;
    if (this.records.size >= recordLimit) {
      throw new Error(
        `rehearsal capture is limited to ${COLLECTOR_LIMITS.maximumCollectedRecords} records`
      );
    }
    this.records.set(candidate.recordId, candidate);
    return candidate;
  }

  ingest(feed) {
    if (this.completed) throw new Error("rehearsal collection is already complete");
    if (
      !isPlainObject(feed) ||
      !Array.isArray(feed.records) ||
      feed.records.length > COLLECTOR_LIMITS.maximumFeedRecords
    ) {
      throw new Error(
        `live feed must contain at most ${COLLECTOR_LIMITS.maximumFeedRecords} records`
      );
    }
    if (this.feedCount >= COLLECTOR_LIMITS.maximumFeeds) {
      throw new Error(
        `rehearsal capture is limited to ${COLLECTOR_LIMITS.maximumFeeds} feeds`
      );
    }
    validateLiveMonitoringFeed(feed);
    if (feed.integrity.manifestSha256 !== liveManifestHash(feed)) {
      throw new Error("live feed manifest does not cover its records");
    }
    const generatedAtMs = parseUtc(feed.generatedAtUtc, "feed.generatedAtUtc");
    if (generatedAtMs < this.startedAtMs) {
      throw new Error("live feed predates the rehearsal");
    }
    if (this.lastFeedAtMs !== null && generatedAtMs < this.lastFeedAtMs) {
      throw new Error("live feed captures must be monotonic");
    }
    const stagedRecords = new Map(this.records);
    const stagedHealth = new Map();
    const stagedFeedIds = new Set(this.feedIds);

    const stageRecord = (record) => {
      const candidate = clone(record);
      delete candidate.sequence;
      const existing = stagedRecords.get(candidate.recordId);
      if (existing) {
        if (stableStringify(existing) !== stableStringify(candidate)) {
          throw new Error(`recordId ${candidate.recordId} changed after capture`);
        }
        return;
      }
      stagedRecords.set(candidate.recordId, candidate);
    };

    for (const record of feed.records) {
      if (record.recordType === "health") {
        if (
          record.provenance.adapter.id === "eu5-local-monitoring-server" &&
          record.provenance.adapter.version === "1" &&
          record.provenance.verification.status === "verified" &&
          record.provenance.verification.evidence === LOCAL_HEALTH_EVIDENCE &&
          record.provenance.freshness === "fresh" &&
          typeof record.payload.component === "string"
        ) {
          stagedHealth.set(record.payload.component, clone(record.payload));
        }
        continue;
      }
      if (!IMPORTED_RECORD_TYPES.has(record.recordType)) continue;
      if (record.captureSessionId !== this.rehearsalId) continue;
      if (
        record.subject.campaignId !== this.fingerprint.campaignId ||
        record.subject.countryId !== this.fingerprint.countryId
      ) {
        throw new Error(`session-bound record ${record.recordId} has the wrong subject`);
      }
      if (record.provenance.freshness !== "fresh") {
        if (!stagedRecords.has(record.recordId)) continue;
        continue;
      }
      if (
        record.recordType.startsWith("llm_action_") &&
        (
          record.provenance.adapter.id !== "eu5-control-ledger" ||
          record.provenance.adapter.version !== "1" ||
          ![LEDGER_UNVERIFIED_EVIDENCE, LEDGER_VERIFIED_EVIDENCE].includes(
            record.provenance.verification.evidence
          ) ||
          (
            record.provenance.verification.status === "verified" &&
            record.provenance.verification.evidence !== LEDGER_VERIFIED_EVIDENCE
          )
        )
      ) {
        throw new Error(`action record ${record.recordId} has untrusted provenance`);
      }
      if (
        record.recordType === "nation_snapshot" &&
        (
          record.provenance.adapter.id !== "eu5-control-bridge" ||
          record.provenance.adapter.version !== "1" ||
          record.provenance.verification.status !== "verified" ||
          record.provenance.verification.evidence !== TELEMETRY_VERIFIED_EVIDENCE
        )
      ) {
        continue;
      }
      const captured = clone(record);
      if (
        captured.recordType === "nation_snapshot" &&
        captured.payload.domain === "player"
      ) {
        captured.payload.domain = "nation";
      }
      stageRecord(captured);
    }
    if (
      stagedRecords.size >
      COLLECTOR_LIMITS.maximumCollectedRecords -
        COLLECTOR_LIMITS.completionRecords
    ) {
      throw new Error(
        `rehearsal capture is limited to ${COLLECTOR_LIMITS.maximumCollectedRecords} records`
      );
    }
    stagedFeedIds.add(feed.feedId);
    this.records = stagedRecords;
    this.sourceHealth = stagedHealth;
    this.feedIds = stagedFeedIds;
    this.lastFeedAtMs = generatedAtMs;
    this.finalFeed = Object.freeze({
      feedId: feed.feedId,
      generatedAtUtc: feed.generatedAtUtc,
      manifestSha256: feed.integrity.manifestSha256
    });
    this.feedCount += 1;
    return Object.freeze({
      feedId: feed.feedId,
      generatedAtUtc: feed.generatedAtUtc,
      capturedRecords: this.records.size
    });
  }

  recordBoundedAdvance({
    beforeRecordId,
    afterRecordId,
    maximumDays,
    recordedAtUtc
  }) {
    if (!Number.isSafeInteger(maximumDays) || maximumDays < 1) {
      throw new TypeError("maximumDays must be a positive integer");
    }
    const before = this.records.get(requireString(beforeRecordId, "beforeRecordId"));
    const after = this.records.get(requireString(afterRecordId, "afterRecordId"));
    for (const [label, record] of [["before", before], ["after", after]]) {
      if (
        !record ||
        record.recordType !== "nation_snapshot" ||
        record.payload.domain !== "nation" ||
        record.payload.paused !== true ||
        record.provenance.verification.status !== "verified" ||
        record.provenance.freshness !== "fresh"
      ) {
        throw new Error(`${label} evidence is not a verified paused nation snapshot`);
      }
    }
    const beforeDay = gameDateOrdinal(before.payload.gameDate, "before game date");
    const afterDay = gameDateOrdinal(after.payload.gameDate, "after game date");
    const elapsedDays = afterDay - beforeDay;
    if (elapsedDays < 1) throw new Error("bounded advance must move game time forward");
    if (
      before.recordId === after.recordId ||
      Date.parse(before.occurredAtUtc) >= Date.parse(after.occurredAtUtc) ||
      Date.parse(before.recordedAtUtc) >= Date.parse(after.recordedAtUtc)
    ) {
      throw new Error("bounded advance evidence must be a chronologically ordered pair");
    }
    const recordedAtMs = parseUtc(recordedAtUtc, "recordedAtUtc");
    if (
      recordedAtMs < Date.parse(after.recordedAtUtc) ||
      recordedAtMs < this.startedAtMs
    ) {
      throw new Error("bounded advance cannot be recorded before its evidence");
    }
    const beforeHash = recordDigest(before);
    const afterHash = recordDigest(after);
    const evidencePair = `${beforeHash}:${afterHash}`;
    if (this.boundedEvidencePairs.has(evidencePair)) {
      throw new Error("bounded advance evidence pair was already recorded");
    }
    const interval = {
      startMs: Date.parse(before.occurredAtUtc),
      endMs: Date.parse(after.occurredAtUtc)
    };
    if (this.boundedEvidenceIntervals.some((existing) =>
      interval.startMs < existing.endMs &&
      existing.startMs < interval.endMs
    )) {
      throw new Error("bounded advance evidence interval overlaps an existing receipt");
    }
    const pairHash = crypto.createHash("sha256")
      .update(evidencePair)
      .digest("hex");
    const receipt = this.addCollectorRecord({
      recordId: `bounded-advance-${pairHash}`,
      recordType: "game_event",
      occurredAtUtc: after.occurredAtUtc,
      recordedAtUtc: new Date(recordedAtMs).toISOString(),
      payload: {
        eventType: "bounded_time_advance",
        bounded: true,
        beforePaused: true,
        afterPaused: true,
        beforeGameDate: before.payload.gameDate,
        afterGameDate: after.payload.gameDate,
        overshootDays: Math.max(0, elapsedDays - maximumDays),
        beforeEvidenceSha256: beforeHash,
        afterEvidenceSha256: afterHash
      },
      provenance: collectorProvenance(
        "Derived from two captured, independently verified paused nation snapshots.",
        pairHash
      )
    });
    this.boundedEvidencePairs.add(evidencePair);
    this.boundedEvidenceIntervals.push(interval);
    return receipt;
  }

  complete(completedAtUtc) {
    if (this.completed) throw new Error("rehearsal collection is already complete");
    if (
      this.records.size >
      COLLECTOR_LIMITS.maximumCollectedRecords -
        COLLECTOR_LIMITS.completionRecords
    ) {
      throw new Error("rehearsal capture has no capacity for completion records");
    }
    const completedAtMs = parseUtc(completedAtUtc, "completedAtUtc");
    if (completedAtMs < this.startedAtMs) {
      throw new Error("completedAtUtc cannot precede startedAtUtc");
    }
    if (this.lastFeedAtMs === null || completedAtMs < this.lastFeedAtMs) {
      throw new Error("completion must follow at least one captured live feed");
    }
    if (!this.finalFeed) throw new Error("final live feed binding is missing");
    const completed = new Date(completedAtMs).toISOString();
    const hasBridgeRecords = [...this.records.values()].some((record) =>
      record.provenance.adapter.id === "eu5-control-bridge"
    );
    const hasLedgerRecords = [...this.records.values()].some((record) =>
      record.provenance.adapter.id === "eu5-control-ledger"
    );
    const finalFeedBinding = {
      sourceFeedId: this.finalFeed.feedId,
      sourceFeedManifestSha256: this.finalFeed.manifestSha256,
      sourceFeedGeneratedAtUtc: this.finalFeed.generatedAtUtc
    };
    const health = [
      {
        component: "test-session",
        status: "available",
        fingerprint: this.fingerprint
      },
      {
        component: "mod-bridge",
        ...finalFeedBinding,
        status:
          hasBridgeRecords &&
          this.sourceHealth.get("structured-debug-log")?.status === "available"
            ? "available"
            : "unavailable"
      },
      {
        component: "monitoring-feed",
        ...finalFeedBinding,
        status: this.feedCount > 0 ? "available" : "unavailable",
        captureCount: this.feedCount
      },
      {
        component: "control-ledger",
        ...finalFeedBinding,
        status:
          hasLedgerRecords &&
          this.sourceHealth.get("action-ledger")?.status === "available"
            ? "available"
            : "unavailable"
      }
    ];
    const stagedRecords = new Map(this.records);
    const stageCompletionRecord = (record) => {
      const candidate = clone({
        ...record,
        ...this.sessionFields()
      });
      delete candidate.sequence;
      if (stagedRecords.has(candidate.recordId)) {
        throw new Error(`completion recordId ${candidate.recordId} already exists`);
      }
      if (stagedRecords.size >= COLLECTOR_LIMITS.maximumCollectedRecords) {
        throw new Error("rehearsal capture exceeds the final record limit");
      }
      stagedRecords.set(candidate.recordId, candidate);
    };
    for (const payload of health) {
      stageCompletionRecord({
        recordId: `rehearsal-health-${this.rehearsalId}-${payload.component}`,
        recordType: "health",
        occurredAtUtc: completed,
        recordedAtUtc: completed,
        payload,
        provenance: collectorProvenance(
          payload.component === "test-session"
            ? "Collector session binding matched a separately captured read-only baseline artifact."
            : "Collector health derived from a validated local-live feed and explicit rehearsal binding.",
          payload.component === "test-session"
            ? this.fingerprintEvidenceSha256
            : undefined
        )
      });
    }
    stageCompletionRecord({
      recordId: `rehearsal-completed-${this.rehearsalId}`,
      recordType: "game_event",
      occurredAtUtc: completed,
      recordedAtUtc: completed,
      payload: {
        eventType: "rehearsal_completed",
        rehearsalId: this.rehearsalId
      },
      provenance: collectorProvenance(
        "Explicit local rehearsal capture boundary."
      )
    });

    const records = [...stagedRecords.values()]
      .sort((left, right) =>
        Date.parse(left.occurredAtUtc) - Date.parse(right.occurredAtUtc) ||
        Date.parse(left.recordedAtUtc) - Date.parse(right.recordedAtUtc) ||
        left.recordId.localeCompare(right.recordId)
      )
      .map((record, sequence) => ({ ...record, sequence }));
    const bundle = {
      schemaVersion: "eu5.monitoring-bundle/v1",
      bundleId: this.rehearsalId,
      generatedAtUtc: completed,
      sourceMode: "offline-import",
      records,
      integrity: {}
    };
    bundle.integrity.manifestSha256 = computeMonitoringManifestHash(bundle);
    validateMonitoringBundle(bundle);
    this.records = stagedRecords;
    this.completed = true;
    return deepFreeze(bundle);
  }
}

module.exports = {
  COLLECTOR_ADAPTER,
  COLLECTOR_LIMITS,
  StreamRehearsalCollector,
  gameDateOrdinal,
  liveManifestHash,
  recordDigest
};
